INSERT INTO products (name, brand, category, description, long_description, price, emoji, stock, specs, image_url, banner_order, banner_title, banner_text, banner_color) VALUES
  ('Lavazza Qualità Oro, 1 кг', 'Lavazza', 'Кофе', 'Кофе в зёрнах, 100% арабика, средняя обжарка', 'Qualità Oro это первая смесь Lavazza, придуманная в 1956 году. Это 100% арабика из шести сортов средней обжарки: сладкий вкус с цветочными и фруктовыми нотами и долгим послевкусием. Подходит для эспрессо, капучино и кофемашин с зерном. Пакет с обратным клапаном защищает зёрна от воздуха, влаги и света, поэтому кофе дольше остаётся свежим.', 335000, '☕', 50, '[{"k": "Состав", "v": "100% арабика, смесь из 6 сортов"}, {"k": "Обжарка", "v": "Средняя"}, {"k": "Вкус", "v": "Цветочные и фруктовые нотки, сладкое послевкусие"}, {"k": "Профиль (из 5)", "v": "Аромат 5, плотность 4, крепость 3, обжарка 3, кислотность 2"}, {"k": "Формат", "v": "Зёрна, 1 кг"}, {"k": "Страна", "v": "Италия"}, {"k": "Упаковка", "v": "Пакет с клапаном для сохранения свежести"}, {"k": "С чего началось", "v": "Первая смесь Lavazza, с 1956 года"}]'::jsonb, '/img/lavazza-qualita-oro-1kg.jpg', 1, 'Утро начинается с хорошего кофе', 'Сто процентов арабика, средняя обжарка и цветочно-фруктовые ноты: классика Lavazza с 1956 года.', '#a8643a'),
  ('Sony WH-CH720N', 'Sony', 'Наушники', 'Беспроводные наушники с шумоподавлением и до 35 часов работы', 'Самые лёгкие наушники Sony с активным шумоподавлением: всего 192 г. Тот же процессор V1, что и в флагманской линейке WH-1000X, отвечает за звук и подавление шума. Можно подключить сразу два устройства, а когда заряд заканчивается, слушать по проводу. В приложении Sony Headphones Connect настраивается уровень окружающих звуков.', 1815000, '🎧', 12, '[{"k": "Тип", "v": "Беспроводные, закрытого типа"}, {"k": "Шумоподавление", "v": "Активное, процессор Sony V1"}, {"k": "Драйверы", "v": "30 мм"}, {"k": "Bluetooth", "v": "5.2, подключение к двум устройствам одновременно"}, {"k": "Автономность", "v": "До 35 ч с шумоподавлением, до 50 ч без него"}, {"k": "Частотный диапазон", "v": "20 Гц – 20 кГц"}, {"k": "Вес", "v": "192 г"}, {"k": "Разъёмы", "v": "USB-C для зарядки, 3,5 мм для провода"}, {"k": "Цвета", "v": "Чёрный, белый, синий"}]'::jsonb, '/img/sony-wh-ch720n.jpg', 2, 'Тишина по кнопке', 'Активное шумоподавление с чипом Sony V1 и до 35 часов музыки без подзарядки.', '#3f7a9c'),
  ('Xiaomi Smart Band 9', 'Xiaomi', 'Фитнес-браслеты', 'Яркий AMOLED-экран, защита 5 ATM и до 21 дня без подзарядки', 'Лёгкий браслет с крупным AMOLED-экраном 1,62 дюйма и яркостью до 1200 нит читается даже на солнце. Отслеживает пульс и физическую активность, а защита 5 ATM позволяет не снимать его в душе и бассейне. Одной зарядки хватает примерно на три недели при обычном использовании, а заряжается браслет около часа. Работает со смартфонами на Android и iOS через приложение Mi Fitness.', 545000, '⌚', 30, '[{"k": "Экран", "v": "AMOLED 1,62\", 192 × 490, яркость до 1200 нит"}, {"k": "Автономность", "v": "До 21 дня при обычном использовании"}, {"k": "Аккумулятор", "v": "233 мА·ч, магнитная зарядка около 1 часа"}, {"k": "Водозащита", "v": "5 ATM"}, {"k": "Датчики", "v": "Оптический пульсометр, акселерометр, гироскоп, датчик освещённости"}, {"k": "Корпус", "v": "46,5 × 21,6 × 11 мм, 15,8 г без ремешка"}, {"k": "Ремешок", "v": "TPU, обхват 135–210 мм"}, {"k": "Совместимость", "v": "Android 8.0+ и iOS 12+, приложение Mi Fitness"}]'::jsonb, '/img/xiaomi-smart-band-9.jpg', 3, 'Три недели без зарядки', 'Яркий AMOLED-экран, защита от воды и до 21 дня работы от одной зарядки.', '#5c8a5a'),
  ('JBL Go 4', 'JBL', 'Колонки', 'Компактная защищённая колонка: IP67 и до 7 часов музыки', 'Колонка размером с ладонь, которую удобно брать на пикник, в поездку или на пляж. Защита IP67 справляется с пылью и погружением в воду. Две колонки Go 4 можно соединить для стереозвука, а функция Auracast объединяет несколько совместимых колонок JBL. В приложении JBL Portable есть эквалайзер и режим Playtime Boost, продлевающий работу.', 605000, '🔊', 25, '[{"k": "Тип", "v": "Портативная Bluetooth-колонка"}, {"k": "Мощность", "v": "4,2 Вт"}, {"k": "Диапазон частот", "v": "90 Гц – 20 кГц"}, {"k": "Bluetooth", "v": "5.3, Auracast"}, {"k": "Защита", "v": "IP67: пыль и вода"}, {"k": "Автономность", "v": "До 7 ч, до 9 ч в режиме Playtime Boost"}, {"k": "Аккумулятор", "v": "850 мА·ч, зарядка по USB-C около 3 ч"}, {"k": "Размеры", "v": "Около 94 × 78 × 42 мм"}, {"k": "Вес", "v": "190 г"}]'::jsonb, '/img/jbl-go-4.jpg', NULL, NULL, NULL, NULL),
  ('Xiaomi Power Bank 20000, 22,5 Вт', 'Xiaomi', 'Аксессуары', 'Ёмкий внешний аккумулятор с быстрой зарядкой 22,5 Вт', 'Внешний аккумулятор, которого хватает на несколько зарядок смартфона. Встроенный кабель USB-C избавляет от поиска провода, а разъёмы USB-C и USB-A позволяют заряжать несколько устройств сразу. Суммарная мощность до 22,5 Вт. Ёмкость 74 Вт·ч укладывается в правила большинства авиакомпаний для ручной клади (до 100 Вт·ч).', 305000, '🔋', 40, '[{"k": "Ёмкость", "v": "20 000 мА·ч (74 Вт·ч)"}, {"k": "Мощность выхода", "v": "До 22,5 Вт"}, {"k": "Порты", "v": "Встроенный кабель USB-C, USB-C, USB-A"}, {"k": "Вход", "v": "USB-C: 5 В / 3 А, 9 В / 2,5 А"}, {"k": "Размеры", "v": "128 × 73 × 32 мм"}, {"k": "Вес", "v": "342 г"}, {"k": "Модель", "v": "PB2020MI"}]'::jsonb, '/img/xiaomi-power-bank-20000.jpg', NULL, NULL, NULL, NULL),
  ('Stanley Classic Legendary Bottle, 750 мл', 'Stanley', 'Термосы', 'Легендарный стальной термос: до 20 часов тепла или холода', 'Знаменитая стальная бутылка-термос, которую делают много лет и которой не страшны удары и падения. Двойные стенки с вакуумной изоляцией держат напиток горячим или холодным до 20 часов, а со льдом холод сохраняется до четырёх суток. Крышка герметична и служит ещё и чашкой. Корпус из нержавеющей стали 18/8, без BPA.', 760000, '🧴', 4, '[{"k": "Объём", "v": "750 мл"}, {"k": "Материал", "v": "Нержавеющая сталь 18/8"}, {"k": "Изоляция", "v": "Двойные стенки, вакуум"}, {"k": "Сохраняет", "v": "До 20 ч тепло или холод, до 4 суток со льдом"}, {"k": "Размеры", "v": "Высота 30,8 см, диаметр 8,5 см"}, {"k": "Вес", "v": "Около 600 г"}, {"k": "Комплект", "v": "Герметичная крышка-чашка"}, {"k": "Безопасность", "v": "Без BPA, можно мыть в посудомоечной машине"}]'::jsonb, '/img/stanley-classic-750.jpg', NULL, NULL, NULL, NULL);
